import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_20th_good_number():
    m_values = set()
    limit = 100  # Set a reasonable upper limit for x and y to find the 20th value

    # Iterate over pairs (x, y) where x < y
    for x in range(1, limit + 1):
        for y in range(x + 1, limit + 1):
            if gcd(x, y) > 1:
                m = x**2 + y**2
                m_values.add(m)

    sorted_m = sorted(list(m_values))

    if len(sorted_m) < 20:
        print("Did not find 20 distinct values within the search limit.")
        return None

    # Return the 20th smallest value (index 19)
    return sorted_m[19]

result = find_20th_good_number()
print(f"The 20th smallest value found is: {result}")

# Also print the first few and the 20th value to confirm the search process
if result is not None:
    # Rerun to list more values for confirmation
    m_values = set()
    limit = 100
    for x in range(1, limit + 1):
        for y in range(x + 1, limit + 1):
            if gcd(x, y) > 1:
                m = x**2 + y**2
                m_values.add(m)

    sorted_m = sorted(list(m_values))

    print("\nFirst 30 smallest values:")
    for i in range(min(30, len(sorted_m))):
        print(sorted_m[i])
    print(f"\nThe 20th smallest value (index 19) is: {sorted_m[19]}")

